namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and specializes in programming language design.", IsFeatured = true, DepartmentCode = "CS", DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a researcher in algorithm optimization with publications in top-tier conferences. Previously worked at Google Research.", IsFeatured = true, DepartmentCode = "CS", DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 350", Title = "Operating Systems", Description = "Covers process management, memory management, file systems, and concurrency. Includes hands-on kernel programming projects.", Credits = 4, Schedule = "Mon/Wed 2:00–3:30 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez contributed to the Linux kernel for over a decade before joining academia. She brings real-world systems experience to the classroom.", IsFeatured = false, DepartmentCode = "CS", DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus: limits, derivatives, and applications. Emphasis on problem-solving techniques.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning educator with a passion for making calculus accessible. He authored two widely-used textbooks.", IsFeatured = true, DepartmentCode = "MATH", DepartmentName = "Mathematics" },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 220", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson specializes in applied mathematics and has collaborated with NASA on trajectory modeling.", IsFeatured = false, DepartmentCode = "MATH", DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 3, CourseCode = "ENG 101", Title = "College Composition", Description = "Develop critical thinking and writing skills through essay writing, research, and peer review.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is a published author and writing coach with experience mentoring students from diverse backgrounds.", IsFeatured = false, DepartmentCode = "ENG", DepartmentName = "English" },
            new() { Id = 7, DepartmentId = 3, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and society.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", InstructorName = "Dr. Lisa Grant", InstructorBio = "Dr. Grant is a scholar of 20th-century American fiction and has published extensively on Toni Morrison and James Baldwin.", IsFeatured = true, DepartmentCode = "ENG", DepartmentName = "English" },
            new() { Id = 8, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist whose research focuses on quantum optics. He has mentored dozens of undergraduate researchers.", IsFeatured = false, DepartmentCode = "PHYS", DepartmentName = "Physics" },
            new() { Id = 9, DepartmentId = 4, CourseCode = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, and measurement.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel is a theoretical physicist with groundbreaking work in quantum computing. She previously held a research position at CERN.", IsFeatured = true, DepartmentCode = "PHYS", DepartmentName = "Physics" },
            new() { Id = 10, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural exchanges, and turning points from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 3:00–4:30 PM", InstructorName = "Dr. Thomas Reed", InstructorBio = "Dr. Reed is a historian specializing in ancient Mediterranean societies. He has led archaeological excavations in Greece and Turkey.", IsFeatured = false, DepartmentCode = "HIST", DepartmentName = "History" },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST 320", Title = "The Civil Rights Movement", Description = "In-depth study of the American civil rights movement from the 1950s through the 1970s, examining key figures, legislation, and legacy.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", InstructorName = "Dr. Angela Brooks", InstructorBio = "Dr. Brooks is a leading voice in civil rights history and has served as a consultant for several award-winning documentaries.", IsFeatured = false, DepartmentCode = "HIST", DepartmentName = "History" }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null, int? minCredits = null, int? maxCredits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (minCredits.HasValue)
        {
            query = query.Where(c => c.Credits >= minCredits.Value);
        }

        if (maxCredits.HasValue)
        {
            query = query.Where(c => c.Credits <= maxCredits.Value);
        }

        return query.OrderBy(c => c.CourseCode).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

